// Package postgres implements the catalog ports on PostgreSQL (schema
// "catalog"), with queries generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/meepleo/meepleo-api/internal/catalog/adapters/out/postgres/sqlcgen"
	"github.com/meepleo/meepleo-api/internal/catalog/app"
	"github.com/meepleo/meepleo-api/internal/catalog/domain"
	"github.com/meepleo/meepleo-api/internal/platform/postgres"
)

// Repository implements app.Games, app.Queue, app.Attempts and app.TxManager.
type Repository struct {
	pool *pgxpool.Pool
	q    *sqlcgen.Queries
}

// NewRepository returns a Repository on pool.
func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool, q: sqlcgen.New(pool)}
}

// ByID loads a full game sheet: the game row, its rules, sources and warnings.
func (r *Repository) ByID(ctx context.Context, id domain.GameID) (domain.Game, error) {
	row, err := r.q.GetGame(ctx, int64(id))
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Game{}, domain.ErrGameNotFound
	}
	if err != nil {
		return domain.Game{}, fmt.Errorf("select game: %w", err)
	}
	g, err := toGame(row)
	if err != nil {
		return domain.Game{}, err
	}

	rules, err := r.q.ListRuleItems(ctx, int64(id))
	if err != nil {
		return domain.Game{}, fmt.Errorf("select rule items: %w", err)
	}
	for _, rr := range rules {
		item, err := toRuleItem(rr)
		if err != nil {
			return domain.Game{}, err
		}
		g.Rules = append(g.Rules, item)
	}

	sources, err := r.q.ListSources(ctx, int64(id))
	if err != nil {
		return domain.Game{}, fmt.Errorf("select sources: %w", err)
	}
	for _, s := range sources {
		g.Sources = append(g.Sources, domain.Source{Title: s.Title, URL: s.Url})
	}

	warnings, err := r.q.ListWarnings(ctx, int64(id))
	if err != nil {
		return domain.Game{}, fmt.Errorf("select warnings: %w", err)
	}
	for _, w := range warnings {
		t, err := fromLocalizedJSON(w)
		if err != nil {
			return domain.Game{}, err
		}
		g.Warnings = append(g.Warnings, t)
	}
	return g, nil
}

// Resolution returns what is known about a barcode.
func (r *Repository) Resolution(ctx context.Context, code domain.Barcode) (domain.BarcodeResolution, bool, error) {
	row, err := r.q.GetBarcode(ctx, string(code))
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.BarcodeResolution{}, false, nil
	}
	if err != nil {
		return domain.BarcodeResolution{}, false, fmt.Errorf("select barcode: %w", err)
	}
	res := toResolution(row)
	if res.Status == domain.BarcodeAmbiguous {
		rows, err := r.q.ListBarcodeCandidates(ctx, string(code))
		if err != nil {
			return domain.BarcodeResolution{}, false, fmt.Errorf("select candidates: %w", err)
		}
		for _, c := range rows {
			res.Candidates = append(res.Candidates, domain.Candidate{
				Name:      c.Name,
				Edition:   c.Edition.String,
				Publisher: c.Publisher.String,
				Year:      int(c.Year.Int16),
				GameID:    domain.GameID(c.GameID.Int64),
			})
		}
	}
	return res, true, nil
}

// Enqueue adds a barcode to the generation queue or raises its priority.
func (r *Repository) Enqueue(ctx context.Context, code domain.Barcode) error {
	if err := r.q.EnqueueBarcode(ctx, string(code)); err != nil {
		return fmt.Errorf("enqueue barcode: %w", err)
	}
	return nil
}

// Claim leases the highest-priority claimable barcode.
func (r *Repository) Claim(ctx context.Context, now time.Time, lease time.Duration) (app.QueuedBarcode, bool, error) {
	row, err := r.q.ClaimBarcode(ctx, sqlcgen.ClaimBarcodeParams{
		Now:         timestamptz(now),
		LockedUntil: timestamptz(now.Add(lease)),
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return app.QueuedBarcode{}, false, nil
	}
	if err != nil {
		return app.QueuedBarcode{}, false, fmt.Errorf("claim barcode: %w", err)
	}
	return app.QueuedBarcode{
		Barcode:      domain.Barcode(row.Barcode),
		RequestCount: int(row.RequestCount),
		Attempts:     int(row.Attempts),
	}, true, nil
}

// CountSince counts generation attempts since a date.
func (r *Repository) CountSince(ctx context.Context, since time.Time) (int, error) {
	n, err := r.q.CountAttemptsSince(ctx, timestamptz(since))
	if err != nil {
		return 0, fmt.Errorf("count attempts: %w", err)
	}
	return int(n), nil
}

// WithinTx runs fn in a transaction with a Store bound to it.
func (r *Repository) WithinTx(ctx context.Context, fn func(context.Context, app.Store) error) error {
	return postgres.WithTx(ctx, r.pool, func(tx pgx.Tx) error {
		return fn(ctx, &store{q: r.q.WithTx(tx)})
	})
}

// store implements app.Store on a transaction.
type store struct {
	q *sqlcgen.Queries
}

func (s *store) SaveGame(ctx context.Context, g domain.Game, raw []byte) (domain.GameID, error) {
	params, err := gameParams(g, raw)
	if err != nil {
		return 0, err
	}
	id, err := s.q.InsertGame(ctx, params)
	if err != nil {
		return 0, fmt.Errorf("insert game: %w", mapErr(err))
	}
	for _, rule := range g.Rules {
		p, err := ruleItemParams(id, rule)
		if err != nil {
			return 0, err
		}
		if err := s.q.InsertRuleItem(ctx, p); err != nil {
			return 0, fmt.Errorf("insert rule item %q: %w", rule.Key, mapErr(err))
		}
	}
	for _, src := range g.Sources {
		if err := s.q.InsertSource(ctx, sqlcgen.InsertSourceParams{GameID: id, Title: src.Title, Url: src.URL}); err != nil {
			return 0, fmt.Errorf("insert source: %w", err)
		}
	}
	for i, w := range g.Warnings {
		b, err := localizedJSON(w)
		if err != nil {
			return 0, err
		}
		if err := s.q.InsertWarning(ctx, sqlcgen.InsertWarningParams{GameID: id, SortOrder: int16(i + 1), Text: b}); err != nil { //nolint:gosec // few warnings
			return 0, fmt.Errorf("insert warning: %w", err)
		}
	}
	return domain.GameID(id), nil
}

func (s *store) SaveResolution(ctx context.Context, res domain.BarcodeResolution) error {
	if err := s.q.UpsertBarcode(ctx, sqlcgen.UpsertBarcodeParams{
		Barcode:      string(res.Barcode),
		Status:       sqlcgen.CatalogBarcodeStatus(res.Status),
		GameID:       int8(res.GameID),
		EditionLabel: text(res.EditionLabel),
		Source:       sqlcgen.CatalogBarcodeSource(res.Source),
		CheckedAt:    timestamptz(res.CheckedAt),
		RetryAfter:   timestamptz(res.RetryAfter),
	}); err != nil {
		return fmt.Errorf("upsert barcode: %w", mapErr(err))
	}
	if err := s.q.DeleteBarcodeCandidates(ctx, string(res.Barcode)); err != nil {
		return fmt.Errorf("delete candidates: %w", err)
	}
	for _, c := range res.Candidates {
		if err := s.q.InsertBarcodeCandidate(ctx, sqlcgen.InsertBarcodeCandidateParams{
			Barcode:   string(res.Barcode),
			Name:      c.Name,
			Edition:   text(c.Edition),
			Publisher: text(c.Publisher),
			Year:      int2(c.Year),
			GameID:    int8(c.GameID),
		}); err != nil {
			return fmt.Errorf("insert candidate: %w", mapErr(err))
		}
	}
	return nil
}

func (s *store) Dequeue(ctx context.Context, code domain.Barcode) error {
	if err := s.q.DequeueBarcode(ctx, string(code)); err != nil {
		return fmt.Errorf("dequeue barcode: %w", err)
	}
	return nil
}

func (s *store) Reschedule(ctx context.Context, code domain.Barcode, lastError string, lockedUntil time.Time) error {
	if err := s.q.RescheduleBarcode(ctx, sqlcgen.RescheduleBarcodeParams{
		Barcode:     string(code),
		LastError:   text(lastError),
		LockedUntil: timestamptz(lockedUntil),
	}); err != nil {
		return fmt.Errorf("reschedule barcode: %w", err)
	}
	return nil
}

func (s *store) RecordAttempt(ctx context.Context, a app.Attempt) error {
	if err := s.q.InsertAttempt(ctx, sqlcgen.InsertAttemptParams{
		Barcode:     string(a.Barcode),
		AttemptedAt: timestamptz(a.AttemptedAt),
		Outcome:     a.Outcome,
		Model:       text(a.Model),
	}); err != nil {
		return fmt.Errorf("insert attempt: %w", err)
	}
	return nil
}

// mapErr turns constraint violations into domain errors so they never leak as
// SQL errors.
func mapErr(err error) error {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case "23505": // unique_violation
			return fmt.Errorf("%w: %s", domain.ErrConflict, pgErr.ConstraintName)
		case "23514", "23502", "22P02": // check / not null / invalid enum text
			return fmt.Errorf("%w: %s", domain.ErrInvalidGame, pgErr.ConstraintName)
		}
	}
	return err
}
